const ROLE_NAMES={student:'תלמיד',parent:'הורה',teacher:'מורה',manager:'מנהל בית ספר',admin:'אדמין'};
function roleUsers(){return cloud.ready?cloud.profiles:[...school.students.map(s=>({id:s.id,display_name:s.name,role:'student'})),...school.teachers.map(t=>({id:t.id,display_name:t.name,role:'teacher'})),{id:'manager-demo',display_name:'מנהל בית הספר',role:'manager'},{id:'admin-demo',display_name:'אדמין מערכת',role:'admin'}]}
function renderRoleRequests(){const box=document.getElementById('roleRequests'),mine=document.getElementById('myRoleRequest');if(!box)return;if(!cloud.ready){mine.hidden=true;box.textContent='';return}const requests=cloud.roleRequests||[];const own=requests.find(r=>r.user_id===cloud.user?.id&&r.status==='pending');mine.hidden=!own;if(own)mine.textContent=t('בקשת התפקיד שלך ממתינה לאישור אדמין:')+' '+t(ROLE_NAMES[own.requested_role]||own.requested_role);const pending=role==='admin'?requests.filter(r=>r.status==='pending'):[];box.textContent='';if(role==='admin'&&!pending.length){const p=document.createElement('p');p.textContent=t('אין בקשות תפקיד ממתינות.');box.append(p)}for(const r of pending){const name=cloud.profiles.find(u=>u.id===r.user_id)?.display_name||r.user_id;const row=document.createElement('div');row.className='side-row';const label=document.createElement('span');label.textContent=name+' · '+t(ROLE_NAMES[r.requested_role]||r.requested_role);label.setAttribute('data-user-content','');const actions=document.createElement('span');for(const [approve,text] of [[true,'אישור'],[false,'דחייה']]){const b=document.createElement('button');b.type='button';b.className=approve?'button':'secondary';b.textContent=t(text);b.onclick=async()=>{const status=document.getElementById('roleStatus');try{await cloudResult(cloud.client.rpc('decide_school_role_request',{target_user:r.user_id,approve}));await cloudRefresh();status.textContent='✓ '+t(approve?'הבקשה אושרה.':'הבקשה נדחתה.')}catch(e){status.textContent=e.message}};actions.append(b)}row.append(label,actions);box.append(row)}}
function renderRoleManagement(){renderRoleRequests();if(typeof renderChildren==='function')renderChildren();if(typeof renderDemoBar==='function')renderDemoBar();document.getElementById('systemRoleEditor').hidden=role!=='admin';const selected=document.getElementById('roleUser').value;fillAdminSelect(document.getElementById('roleUser'),roleUsers().map(u=>({id:u.id,name:u.display_name+' · '+ROLE_NAMES[u.role]})),selected);const user=roleUsers().find(u=>u.id===document.getElementById('roleUser').value);if(user)document.getElementById('newSystemRole').value=user.role;fillAdminSelect(document.getElementById('assignmentTeacher'),school.teachers.filter(t=>school.staff.some(s=>s.schoolId===activeSchoolId()&&s.userId===t.id&&s.role==='teacher')||t.classIds.some(id=>school.classes.some(c=>c.id===id&&c.schoolId===activeSchoolId()))),'');fillAdminSelect(document.getElementById('assignmentClass'),school.classes.filter(c=>c.schoolId===activeSchoolId()),activeClassId())}
document.getElementById('roleUser').onchange=()=>{const user=roleUsers().find(u=>u.id===document.getElementById('roleUser').value);if(user)document.getElementById('newSystemRole').value=user.role};
document.getElementById('saveSystemRole').onclick=async()=>{const status=document.getElementById('roleStatus');try{if(role!=='admin')throw new Error(t('אדמין בלבד.'));const id=document.getElementById('roleUser').value,newRole=document.getElementById('newSystemRole').value;if(!ROLE_NAMES[newRole])throw new Error('Invalid role');if(cloud.ready){await cloudResult(cloud.client.rpc('set_school_user_role',{target_user:id,new_role:newRole}));await cloudRefresh()}else throw new Error('שינוי תפקיד חשבון אמיתי זמין לאחר חיבור Supabase. בדמו בחרו תצוגה בסרגל העליון.');status.textContent='✓ '+t('התפקיד עודכן.')}catch(e){status.textContent=e.message}};
async function updateTeacherAssignment(remove=false){const status=document.getElementById('roleStatus');try{if(!canAdminSchool())throw new Error('אין הרשאה לבית הספר.');const userId=document.getElementById('assignmentTeacher').value,classId=document.getElementById('assignmentClass').value;const classroom=school.classes.find(c=>c.id===classId);if(!userId||!classroom||classroom.schoolId!==activeSchoolId())throw new Error('בחרו מורה וכיתה בבית הספר המורשה.');if(cloud.ready){if(remove)await cloudResult(cloud.client.rpc('remove_school_teacher_assignment',{teacher_user:userId,target_class:classId}));else await cloudResult(cloud.client.from('school_members').upsert({class_id:classId,user_id:userId,member_role:'teacher'},{onConflict:'class_id,user_id'}));await cloudRefresh()}else{const teacher=school.teachers.find(t=>t.id===userId);teacher.classIds=remove?teacher.classIds.filter(id=>id!==classId):[...new Set([...teacher.classIds,classId])];saveSchool();render()}status.textContent=remove?'השיוך הוסר.':'השיוך נשמר.'}catch(e){status.textContent=e.message}}
document.getElementById('saveTeacherAssignment').onclick=()=>updateTeacherAssignment();document.getElementById('removeTeacherAssignment').onclick=()=>updateTeacherAssignment(true);renderRoleManagement();

document.getElementById('setPrimaryTeacher').onclick=async()=>{const status=document.getElementById('roleStatus');try{if(!canAdminSchool())throw new Error('אין הרשאה לבית הספר.');const teacher=document.getElementById('assignmentTeacher').value,classId=document.getElementById('assignmentClass').value;if(!teacher||!school.classes.some(c=>c.id===classId&&c.schoolId===activeSchoolId()))throw new Error('בחרו מורה וכיתה מורשים.');if(cloud.ready){await cloudResult(cloud.client.rpc('set_primary_school_teacher',{teacher_user:teacher,target_class:classId}));await cloudRefresh()}else{const classroom=school.classes.find(c=>c.id===classId);classroom.ownerId=teacher;const member=school.teachers.find(t=>t.id===teacher);member.classIds=[...new Set([...member.classIds,classId])];saveSchool();render()}status.textContent='המורה האחראי עודכן. ניתן להסיר את שיוך המורה הקודם בנפרד.'}catch(e){status.textContent=e.message}};
